"""2_Model_Performance.py
Streamlit page displaying training/evaluation metrics, loss/accuracy curves, confusion matrix, ROC curve, and classification report.
"""
import streamlit as st
import os
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

# Paths to assets generated by training/evaluation scripts
TRAINING_HISTORY = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "assets", "training_history.csv"))
TEST_METRICS = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "assets", "test_metrics.csv"))
CONF_MATRIX = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "assets", "confusion_matrix.png"))
ROC_CURVE = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "assets", "roc_curve.png"))

def _load_history():
    if os.path.exists(TRAINING_HISTORY):
        return pd.read_csv(TRAINING_HISTORY)
    return None

def _load_test_metrics():
    if os.path.exists(TEST_METRICS):
        return pd.read_csv(TEST_METRICS)
    return None

def run():
    st.title("📈 Model Performance Dashboard")
    st.subheader("Training / Validation curves")
    history = _load_history()
    if history is not None:
        fig, ax = plt.subplots(1, 2, figsize=(12, 4))
        ax[0].plot(history["accuracy"], label="train")
        ax[0].plot(history.get("val_accuracy", []), label="val")
        ax[0].set_title("Accuracy")
        ax[0].set_xlabel("Epoch")
        ax[0].legend()
        ax[1].plot(history["loss"], label="train")
        ax[1].plot(history.get("val_loss", []), label="val")
        ax[1].set_title("Loss")
        ax[1].set_xlabel("Epoch")
        ax[1].legend()
        st.pyplot(fig)
    else:
        st.info("Training history not found. Run `python src/train.py` first.")

    st.subheader("Test‑set metrics")
    test_metrics = _load_test_metrics()
    if test_metrics is not None:
        st.table(test_metrics.set_index("Metric"))
    else:
        st.info("Test metrics not found. Run `python src/evaluate.py` first.")

    st.subheader("Confusion Matrix")
    if os.path.exists(CONF_MATRIX):
        st.image(CONF_MATRIX, caption="Confusion Matrix", use_column_width=True)
    else:
        st.info("Confusion matrix image not available.")

    st.subheader("ROC Curve")
    if os.path.exists(ROC_CURVE):
        st.image(ROC_CURVE, caption="ROC Curve", use_column_width=True)
    else:
        st.info("ROC curve image not available.")

